model_name = arguments.get('model')
if not model_name or model_name not in env:
    result = {'error': 'Model %r not found' % model_name}
else:
    record_id = arguments.get('id')
    if not record_id:
        result = {'error': 'Record ID is required'}
    else:
        body = arguments.get('body', '')
        if not body:
            result = {'error': 'Message body is required'}
        else:
            msg_type = arguments.get('type', 'comment')
            subtype = arguments.get('subtype')
            if msg_type == 'note':
                msg_type = 'comment'
                if not subtype:
                    subtype = 'mail.mt_note'
            if not subtype:
                subtype = 'mail.mt_comment'
            record = env[model_name].browse(record_id)
            msg = record.message_post(
                body=body,
                message_type=msg_type,
                subtype_xmlid=subtype,
            )
            result = {'id': msg.id, 'date': str(msg.date)}

{
    "type": "object",
    "properties": {
        "model": {
            "type": "string",
            "description": "Technical model name."
        },
        "id": {
            "type": "integer",
            "description": "The record ID to post the message on."
        },
        "body": {
            "type": "string",
            "description": "The message content (can contain HTML)."
        },
        "type": {
            "type": "string",
            "description": "Message type: 'comment' (visible to followers) or 'note' (internal note).",
            "enum": ["comment", "note"],
            "default": "comment"
        },
        "context": {
            "type": "object",
            "description": "Optional Odoo context overrides."
        }
    },
    "required": ["model", "id", "body"]
}

product_id = arguments.get('id')
if not product_id:
    result = {'error': 'Product ID is required'}
elif not env['product.template'].search_count([('id', '=', product_id)]):
    result = {'error': 'Product template %s not found' % product_id}
else:
    sales_price = arguments.get('sales_price')
    cost_price = arguments.get('cost_price')
    if sales_price is None and cost_price is None:
        result = {'error': 'Provide at least one of: sales_price, cost_price'}
    elif sales_price is not None and float(sales_price) < 0:
        result = {'error': 'sales_price must be >= 0'}
    elif cost_price is not None and float(cost_price) < 0:
        result = {'error': 'cost_price must be >= 0'}
    else:
        product = env['product.template'].browse(product_id)
        vals = {}
        if sales_price is not None:
            vals['list_price'] = float(sales_price)
        if cost_price is not None:
            product.sudo().write({'standard_price': float(cost_price)})
        if vals:
            product.write(vals)
        product.invalidate_recordset()
        result = {
            'id': product.id,
            'name': product.name,
            'sales_price': product.list_price,
            'cost_price': product.sudo().standard_price,
            'updated': list((['sales_price'] if sales_price is not None else []) + (['cost_price'] if cost_price is not None else [])),
        }

