product_id = arguments.get('id')
if not product_id:
    result = {'error': 'Product ID is required'}
elif not env['product.template'].search_count([('id', '=', product_id)]):
    result = {'error': 'Product template %s not found' % product_id}
else:
    name = arguments.get('name')
    internal_reference = arguments.get('internal_reference')
    description = arguments.get('description')
    if not name and internal_reference is None and description is None:
        result = {'error': 'Provide at least one of: name, internal_reference, description'}
    elif name is not None and not str(name).strip():
        result = {'error': 'name cannot be empty'}
    else:
        product = env['product.template'].browse(product_id)
        vals = {}
        if name:
            vals['name'] = str(name).strip()
        if internal_reference is not None:
            vals['default_code'] = str(internal_reference).strip() or False
        if description is not None:
            vals['description_sale'] = str(description).strip() or False
        product.write(vals)
        product.invalidate_recordset()
        result = {
            'id': product.id,
            'name': product.name,
            'internal_reference': product.default_code or '',
            'description': product.description_sale or '',
            'updated': list(vals.keys()),
        }

