partner_id = arguments.get('id')
if not partner_id:
    result = {'error': 'Customer/partner ID is required'}
elif not env['res.partner'].search_count([('id', '=', partner_id)]):
    result = {'error': 'Partner %s not found' % partner_id}
else:
    allowed = ['name', 'email', 'phone', 'street', 'street2', 'city', 'zip']
    vals = {}
    for field in allowed:
        if arguments.get(field) is not None:
            vals[field] = str(arguments[field]).strip() or False
    country_name = arguments.get('country')
    if country_name:
        country = env['res.country'].search([('name', 'ilike', str(country_name).strip())], limit=1)
        if not country:
            result = {'error': 'Country %r not found' % country_name}
            country_name = None
        else:
            vals['country_id'] = country.id
    if not vals and country_name is None:
        result = {'error': 'Provide at least one field to update: name, email, phone, street, street2, city, zip, country'}
    elif vals or country_name:
        partner = env['res.partner'].browse(partner_id)
        partner.write(vals)
        partner.invalidate_recordset()
        result = {
            'id': partner.id,
            'name': partner.name,
            'email': partner.email or '',
            'phone': partner.phone or '',
            'street': partner.street or '',
            'city': partner.city or '',
            'zip': partner.zip or '',
            'country': partner.country_id.name if partner.country_id else '',
            'updated': list(vals.keys()),
        }

