        "city": {"type": "string", "description": "City."},
        "zip": {"type": "string", "description": "Postal / ZIP code."},
        "country": {"type": "string", "description": "Country name (e.g. 'United States')."}
    },
    "required": ["id"]
}

product_id = arguments.get('product_id')
quantity = arguments.get('quantity')
if not product_id:
    result = {'error': 'product_id is required'}
elif quantity is None:
    result = {'error': 'quantity is required'}
elif float(quantity) < 0:
    result = {'error': 'quantity must be >= 0'}
elif not env['product.product'].search_count([('id', '=', product_id)]):
    result = {'error': 'Product (variant) %s not found' % product_id}
else:
    location_id = arguments.get('location_id')
    if location_id:
        location = env['stock.location'].browse(int(location_id))
        if not location.exists():
            result = {'error': 'Location %s not found' % location_id}
            location = None
    else:
        location = env['stock.location'].search(
            [('complete_name', 'ilike', 'WH/Stock'), ('usage', '=', 'internal')], limit=1
        )
        if not location:
            location = env['stock.location'].search([('usage', '=', 'internal')], limit=1)
    if location:
        product = env['product.product'].browse(product_id)
        quant = env['stock.quant'].sudo().search(
            [('product_id', '=', product_id), ('location_id', '=', location.id)], limit=1
        )
        if not quant:
            quant = env['stock.quant'].sudo().create({
                'product_id': product_id,
                'location_id': location.id,
                'quantity': 0,
            })
        quant.sudo().write({'inventory_quantity': float(quantity)})
        quant.sudo().action_apply_inventory()
        quant.invalidate_recordset()
        result = {
            'product_id': product_id,
            'product_name': product.display_name,
            'location': location.complete_name,
            'new_quantity': quant.quantity,
        }

{
    "type": "object",
    "properties": {
        "product_id": {
            "type": "integer",
            "description": "Product variant ID (product.product, not product.template)."
        },
        "quantity": {
            "type": "number",
            "description": "New on-hand quantity to set. Must be >= 0."
        },
        "location_id": {
            "type": "integer",
            "description": "Stock location ID. Defaults to WH/Stock if omitted."
        }
    },
    "required": ["product_id", "quantity"]
}

name = arguments.get('name')
if not name or not str(name).strip():
    result = {'error': 'Product name is required'}
else:
    vals = {'name': str(name).strip()}
    sales_price = arguments.get('sales_price')
    cost_price = arguments.get('cost_price')
    internal_ref = arguments.get('internal_reference')
