    result = {'error': 'Customer name is required'}
else:
    vals = {'name': str(name).strip()}
    for field in ['email', 'phone', 'street', 'street2', 'city', 'zip']:
        if arguments.get(field):
            vals[field] = str(arguments[field]).strip()
