        country = env['res.country'].sudo().search([('name', 'ilike', str(country_name).strip())], limit=1)
        if not country:
            country_error = 'Country %r not found' % country_name
        else:
            vals['country_id'] = country.id
    if country_error:
        result = {'error': country_error}
    else:
        partner = env['res.partner'].sudo().create(vals)
        partner.sudo().write({'customer_rank': 1})
        partner.invalidate_recordset()
        result = {
            'id': partner.id,
            'name': partner.name,
            'email': partner.email or '',
            'phone': partner.phone or '',
            'street': partner.street or '',
            'city': partner.city or '',
            'zip': partner.zip or '',
            'country': partner.country_id.name if partner.country_id else '',
        }

